// Weapon bench data: the guns, their slot trees, the parts and where each comes
// from, generated by scripts/fetch-weapons.mjs from tarkov.dev's JSON dumps
// (data/snapshot/weapons*.json). Loaded lazily the first time the bench opens.

export interface RawSlot {
  /** Slot id within its parent, e.g. "mod_pistol_grip" (unique per parent). */
  n: string;
  /** 1 = the game will not let the gun fire without it. */
  q?: number;
  /** Item ids that fit. */
  i: string[];
}

export interface RawWeapon {
  e?: number;
  rv?: number;
  rh?: number;
  w?: number;
  cal?: string;
  fr?: number;
  cat?: string;
  /** Factory preset item id (its image is the assembled gun). */
  p?: string;
  s?: RawSlot[];
  /** The factory build's parts. */
  d?: string[];
}

export interface RawMod {
  e?: number;
  r?: number;
  a?: number;
  w?: number;
  t?: string;
  cap?: number;
  s?: RawSlot[];
  /** Items that cannot be on the gun together with this one. */
  c?: string[];
}

/** [traderId, loyalty level, price in RUB, taskUnlock id or 0] */
export type RawOffer = [string, number, number, string | 0];
/** [traderId, loyalty level, [[itemId, count]], taskUnlock id or 0] */
export type RawBarter = [string, number, [string, number][], string | 0];
/** [stationId, station level] */
export type RawCraft = [string, number];

export interface RawSource {
  o?: RawOffer[];
  b?: RawBarter[];
  c?: RawCraft[];
  /** Flea average, RUB (absent = cannot be sold on the flea). */
  f?: number;
}

export interface WeaponData {
  generatedAt: string;
  fleaMinLevel: number;
  traders: { id: string; key: string; levels: [number, number][] }[];
  weapons: Record<string, RawWeapon>;
  mods: Record<string, RawMod>;
  src: Record<string, RawSource>;
}

export interface WeaponLocale {
  items: Record<string, [string] | [string, string]>;
  slots: Record<string, string>;
  cats: Record<string, string>;
  traders: Record<string, string>;
  stations: Record<string, string>;
}

const localeModules = import.meta.glob<{ default: WeaponLocale }>('../../data/snapshot/weapons-*.json');

let dataPromise: Promise<WeaponData> | null = null;

export function loadWeaponData(): Promise<WeaponData> {
  dataPromise ??= import('../../data/snapshot/weapons.json').then(
    (m) => (m as unknown as { default: WeaponData }).default,
  );
  return dataPromise;
}

export async function loadWeaponLocale(lang: string): Promise<WeaponLocale> {
  const short = lang.toLowerCase().slice(0, 2);
  const key =
    Object.keys(localeModules).find((k) => k.endsWith(`weapons-${short}.json`)) ??
    Object.keys(localeModules).find((k) => k.endsWith('weapons-en.json'));
  if (!key) return { items: {}, slots: {}, cats: {}, traders: {}, stations: {} };
  return (await localeModules[key]()).default;
}

/** Full name of an item (falls back to its id). */
export function itemName(loc: WeaponLocale, id: string): string {
  return loc.items[id]?.[0] ?? id;
}

/** Short name of an item, or its full name. */
export function itemShort(loc: WeaponLocale, id: string): string {
  const n = loc.items[id];
  return n?.[1] ?? n?.[0] ?? id;
}

/** Label of a slot id: translated, else "mod_scope_001" → "Scope". */
export function slotLabel(loc: WeaponLocale, slot: string): string {
  const v = loc.slots[slot] ?? loc.slots[slot.replace(/_\d+$/, '')];
  if (v) return v;
  const base = slot.replace(/^mod_/, '').replace(/_\d+$/, '').replace(/_/g, ' ');
  return base.charAt(0).toUpperCase() + base.slice(1);
}

/** tarkov.dev images, by item id. */
export const itemIcon = (id: string) => `https://assets.tarkov.dev/${id}-icon.webp`;
export const itemImage = (id: string) => `https://assets.tarkov.dev/${id}-512.webp`;
/** The inventory-cell picture (item on its grid background). */
export const itemGrid = (id: string) => `https://assets.tarkov.dev/${id}-grid-image.webp`;
